<?php
function poc_requests($platform,$number,$status=null){$q=db()->prepare("SELECT r.*,u.name requested_name,a.name approved_name FROM transaction_reversals r JOIN outflows f ON f.id=r.source_id LEFT JOIN users u ON u.id=r.requested_by LEFT JOIN users a ON a.id=r.approved_by WHERE r.source_type='Order Item' AND f.platform=? AND f.order_id=?".($status?' AND r.status=?':'').' ORDER BY r.id');$q->execute($status?[$platform,$number,$status]:[$platform,$number]);return $q->fetchAll();}
function poc_dispatch_date($flow){if(!isset($flow['remarks'])){$q=db()->prepare('SELECT * FROM outflows WHERE id=?');$q->execute([$flow['id']]);$flow=$q->fetch()?:$flow;}if(str_starts_with($flow['remarks']??'','Order item correction;'))foreach(poc_requests($flow['platform'],$flow['order_id'],'Approved') as $r){$p=json_decode($r['result_json'],true);if((int)($p['approval']['new_outflow_id']??0)===(int)$flow['id'])return $p['dispatch_date'];}return $flow['txn_date'];}
function poc_latest_dispatch($oid){$q=db()->prepare("SELECT f.* FROM om_postings p JOIN outflows f ON f.id=p.outflow_id WHERE p.order_id=? AND f.type='Order' AND f.qty>0 AND f.reversed_by_request IS NULL");$q->execute([$oid]);$dates=[];foreach($q as $f)$dates[]=poc_dispatch_date($f);return $dates?max($dates):null;}
function poc_returns_guard($pl,$no){$refs=or_numbers($pl,$no);$marks=implode(',',array_fill(0,count($refs),'?'));$q=db()->prepare("SELECT COUNT(*) FROM posted_returns WHERE platform=? AND original_ref IN ($marks) AND reversed=0");$q->execute(array_merge([$pl],$refs));if($q->fetchColumn())throw new Exception('This order has linked received returns. Review/correct those receipts first.');foreach(db()->query("SELECT rows_json FROM return_batches WHERE status='Review'") as $b)foreach(json_decode($b['rows_json'],true)?:[] as $r)if(($r['platform']??'')===$pl&&in_array((string)($r['order']??''),$refs,true))throw new Exception('An unposted return for this order is under review. Resolve it before correcting its dispatched item.');}
function poc_source($f,$o,$input){$stored=$o?om_query('SELECT * FROM om_lines WHERE order_id=? ORDER BY id',[$o['id']])->fetchAll():[];$candidates=[];
 foreach($stored as $l){$src=json_decode($l['source_json'],true);$cs=json_decode($l['components_json'],true);foreach($cs as $c)if((int)$c['product_id']===(int)$f['product_id'])$candidates[]=['line'=>$src,'components'=>$cs,'line_id'=>(int)$l['id'],'expected'=>(int)$src['qty']*(int)$c['per_bundle']];}
 if($stored){if(count($candidates)!==1||$candidates[0]['expected']!==(int)$f['qty'])throw new Exception('Multiple Seller SKU / bundle lines contributed to this posted quantity. A dedicated source-line review is required; the system will not guess.');$x=$candidates[0];}
 else{$lines=[];$batch=$f['import_batch_id']?om_query('SELECT * FROM import_batches WHERE id=?',[$f['import_batch_id']])->fetch():null;$path=$batch?realpath(__DIR__.'/'.($batch['stored_path']??'')):false;$root=str_replace('\\','/',__DIR__).'/uploads/';if($path&&str_starts_with(str_replace('\\','/',$path),$root)&&is_file($path)){try{foreach(om_parse($f['platform'],$path)['rows'] as $l)if((string)$l['order']===(string)$f['order_id'])$lines[]=$l;}catch(Throwable $e){throw new Exception('The original order file could not be read safely. Review its Seller SKU evidence before correction.');}}
 $exact=array_values(array_filter($lines,fn($l)=>norm($l['item']??'')===norm($f['source_item']??'')||norm(sm_value($l,$f['platform']))===norm($f['source_item']??'')));if(count($exact)===1)$lines=$exact;
 if(count($lines)===1){$src=$lines[0];$units=(int)$src['qty'];if($units<1||(int)$f['qty']%$units!==0)throw new Exception('Posted physical quantity cannot be attributed to the original Seller SKU units.');$x=['line'=>$src,'components'=>[['product_id'=>(int)$f['product_id'],'per_bundle'=>intdiv((int)$f['qty'],$units)]],'line_id'=>0];}
 elseif($lines)throw new Exception('The historical file contains ambiguous source lines. Review the exact Seller SKU / variant before correction.');
 else{if((int)om_query("SELECT COUNT(*) FROM outflows WHERE platform=? AND order_id=? AND type='Order' AND qty>0 AND reversed_by_request IS NULL",[$f['platform'],$f['order_id']])->fetchColumn()!==1)throw new Exception('Historical multi-item order has no complete saved source. Original-file source evidence is required.');$sku=trim((string)($input['seller_sku']??''));if($sku===''||mb_strlen($sku)>255)throw new Exception('Historical source has no saved Seller SKU. Enter its exact Seller SKU from the original file.');if(mb_strlen((string)($input['external_id']??''))>100||mb_strlen((string)($input['variation']??''))>255)throw new Exception('Platform SKU ID or variation is too long.');$src=['order'=>$f['order_id'],'created'=>$f['txn_date'].' 00:00:00','sku'=>$sku,'external'=>trim((string)($input['external_id']??'')),'variation'=>trim((string)($input['variation']??'')),'qty'=>(int)$f['qty'],'item'=>$f['source_item'],'key'=>hash('sha256','legacy-correction|'.$f['id']),'item_ids'=>[]];$x=['line'=>$src,'components'=>[['product_id'=>(int)$f['product_id'],'per_bundle'=>1]],'line_id'=>0];}}
 if(sm_value($x['line'],$f['platform'])==='')throw new Exception('The exact Seller SKU / Parent SKU is required for correction.');return $x;
}
function poc_plan($sourceId,$target,$input=[]){$f=om_query('SELECT * FROM outflows WHERE id=?',[(int)$sourceId])->fetch();if(!$f||$f['type']!=='Order'||(int)$f['qty']<=0||$f['reversed_by_request']!==null)throw new Exception('Select an active posted order item.');stock_platform($f['platform']);$o=om_find($f['platform'],om_shops()[$f['platform']],$f['order_id']);if($o&&$o['posting']!=='Posted')throw new Exception('The registered order is not actively posted.');poc_returns_guard($f['platform'],$f['order_id']);$from=stock_row($f['product_id']);$to=active_product((int)$target);if((int)$to['id']===(int)$from['id'])throw new Exception('Select a different correct Product / SKU.');if(order_return_balance($f['platform'],$f['order_id'],$from['id'])['returned']||order_return_balance($f['platform'],$f['order_id'],$to['id'])['returned'])throw new Exception('Legacy return records must be reviewed first.');
 if($o&&(int)om_query('SELECT COALESCE(SUM(qty),0) FROM om_reservations WHERE order_id=?',[$o['id']])->fetchColumn()>0)throw new Exception('Posted order still has reservations. Resolve that posting exception first.');if($f['import_batch_id']&&(int)om_query("SELECT COUNT(*) FROM transaction_reversals WHERE source_type='Outflow' AND source_id=? AND status='Pending'",[$f['import_batch_id']])->fetchColumn())throw new Exception('A batch reversal is pending. Resolve it before item correction.');if(om_query("SELECT COUNT(*) FROM transaction_reversals WHERE source_type='Manual Outflow' AND source_id=? AND status='Pending'",[$f['id']])->fetchColumn())throw new Exception('A linked reversal is pending. Resolve it first.');$src=poc_source($f,$o,$input);$after=[];foreach($src['components'] as $c){$pid=(int)$c['product_id']===(int)$from['id']?(int)$to['id']:(int)$c['product_id'];$after[$pid]=($after[$pid]??0)+(int)$c['per_bundle'];}ksort($after,SORT_NUMERIC);$components=[];foreach($after as $pid=>$n)$components[]=['product_id'=>$pid,'per_bundle'=>$n];om_component_check($components,true);$shop=$o['shop']??om_shops()[$f['platform']];$mappings=[];foreach(om_query('SELECT * FROM om_mappings WHERE platform=? AND shop=? ORDER BY mapping_key',[$f['platform'],$shop]) as $m)if(sm_identity_match($f['platform'],json_decode($m['source_json'],true)?:[],$src['line']))$mappings[]=$m;
 $p=['type'=>'Order Item','source_id'=>(int)$f['id'],'source'=>$f,'order_record_id'=>(int)($o['id']??0),'order_no'=>$f['order_id'],'platform'=>$f['platform'],'shop'=>$shop,'owner_id'=>(int)($o['owner_id']??$f['user_id']),'batch_id'=>(int)$f['import_batch_id'],'reference'=>$f['platform'].' / '.$f['order_id'].' · outflow #'.$f['id'],'from_id'=>(int)$from['id'],'from_name'=>$from['master_sku'].' · '.$from['name'],'to_id'=>(int)$to['id'],'to_name'=>$to['master_sku'].' · '.$to['name'],'qty'=>(int)$f['qty'],'dispatch_date'=>poc_dispatch_date($f),'source_line'=>$src['line'],'line_id'=>$src['line_id'],'components_before'=>$src['components'],'components_after'=>$components,'mappings_before'=>$mappings,'platforms'=>[['pid'=>(int)$from['id'],'platform'=>$f['platform'],'delta'=>(int)$f['qty']],['pid'=>(int)$to['id'],'platform'=>$f['platform'],'delta'=>-(int)$f['qty']]],'physical_delta'=>0];$p['signature']=hash('sha256',json_encode($p));return $p;
}
function poc_stock_check($p){unset($GLOBALS['OM_RESERVED']);foreach([$p['from_id'],$p['to_id']] as $pid)check_platform_alignment($pid);if(om_available($p['to_id'],$p['platform'])<$p['qty']||om_available($p['to_id'])<$p['qty'])throw new Exception('Insufficient unreserved stock of the correct SKU on '.$p['platform'].'. Review stock / allocation first.');}
function poc_request($input){if(!can_action('resolve_receipt_line'))throw new Exception('Operational correction access required.');if(empty($input['physical_ack']))throw new Exception('Verify the actual dispatched item and Seller SKU against the original order.');$reason=process_reason($input['reason']??'');return process_transaction(function()use($input,$reason){$sid=(int)($input['source_id']??0);om_query('SELECT id FROM outflows WHERE id=? FOR UPDATE',[$sid]);$p=poc_plan($sid,(int)($input['to_id']??0),$input);if(access_profile()!=='Admin'&&$p['owner_id']!==(int)current_user()['id'])throw new Exception('Only the original responsible user or Admin may request this order correction.');if(om_query("SELECT COUNT(*) FROM transaction_reversals WHERE source_type='Order Item' AND source_id=? AND status IN ('Pending','Approved')",[$sid])->fetchColumn())throw new Exception('A correction already exists for this posted source item.');poc_stock_check($p);om_query("INSERT INTO transaction_reversals(source_type,source_id,reason,requested_by,result_json) VALUES('Order Item',?,?,?,?)",[$sid,$reason,current_user()['id'],json_encode($p)]);$rid=(int)db()->lastInsertId();audit('Request posted order item correction','Outflow',$p['reference'],'REV-'.$rid.'; '.$reason.'; no stock / mapping changed.');return $rid;});}
function poc_approve($id){if(current_user()['role']!=='Admin')throw new Exception('Admin approval required.');return process_transaction(function()use($id){$r=om_query('SELECT * FROM transaction_reversals WHERE id=? FOR UPDATE',[$id])->fetch();if(!$r||$r['source_type']!=='Order Item'||$r['status']!=='Pending')throw new Exception('Correction is no longer pending.');$saved=json_decode($r['result_json'],true);om_query('SELECT id FROM outflows WHERE id=? FOR UPDATE',[$saved['source_id']]);if($saved['order_record_id'])om_order($saved['order_record_id'],true);$ids=[$saved['from_id'],$saved['to_id']];sort($ids,SORT_NUMERIC);foreach($ids as $pid)om_query('SELECT id FROM products WHERE id=? FOR UPDATE',[$pid]);$p=poc_plan($saved['source_id'],$saved['to_id'],['seller_sku'=>sm_value($saved['source_line'],$saved['platform']),'external_id'=>$saved['source_line']['external']??'','variation'=>$saved['source_line']['variation']??'']);if(!hash_equals($saved['signature'],$p['signature']))throw new Exception('Order source, return records or Seller SKU mapping changed. Reject and review a new request.');poc_stock_check($p);$date=date('Y-m-d');require_open_inventory_date($date);$ref='REV-'.$id;$note='Order item correction; '.$ref.'; '.$p['reference'].'; '.$r['reason'];
 om_query("INSERT INTO outflows(txn_date,platform,order_id,product_id,source_item,qty,type,import_batch_id,remarks,user_id,reversed_by_request) VALUES(?,?,?,?,?,?,'Order Item Correction',?,?,?,?)",[$date,$p['platform'],$p['order_no'],$p['from_id'],$p['source']['source_item'],-$p['qty'],$p['batch_id']?:null,$note,current_user()['id'],$id]);$undo=(int)db()->lastInsertId();om_query('UPDATE outflows SET reversed_by_request=? WHERE id=?',[$id,$p['source_id']]);om_query("INSERT INTO outflows(txn_date,platform,order_id,product_id,source_item,qty,type,import_batch_id,remarks,user_id) VALUES(?,?,?,?,?,?,'Order',?,?,?)",[$date,$p['platform'],$p['order_no'],$p['to_id'],$p['source']['source_item'],$p['qty'],$p['batch_id']?:null,$note,current_user()['id']]);$newId=(int)db()->lastInsertId();change_platform_stock($p['platform'],$p['from_id'],$p['qty'],$ref,$date);change_platform_stock($p['platform'],$p['to_id'],-$p['qty'],$ref,$date);foreach($ids as $pid)check_platform_alignment($pid);
 $oid=$p['order_record_id'];if(!$oid){om_query("INSERT INTO om_orders(platform,shop,order_no,created_order_at,fulfillment_date,platform_status,posting,monitoring,owner_id,exception_text) VALUES(?,?,?,?,?,'Needs Checking','Posted','Needs Follow-up',?,'Historical posting adopted during item correction; verify platform status.')",[$p['platform'],$p['shop'],$p['order_no'],$p['dispatch_date'].' 00:00:00',$p['dispatch_date'],$p['owner_id']]);$oid=(int)db()->lastInsertId();foreach(om_query("SELECT id FROM outflows WHERE platform=? AND order_id=? AND type='Order' AND qty>0",[$p['platform'],$p['order_no']]) as $f)om_query('INSERT IGNORE INTO om_postings(order_id,outflow_id) VALUES(?,?)',[$oid,$f['id']]);}else om_query('INSERT INTO om_postings(order_id,outflow_id) VALUES(?,?)',[$oid,$newId]);if($p['line_id'])om_query('UPDATE om_lines SET components_json=? WHERE id=?',[json_encode($p['components_after']),$p['line_id']]);
 $line=$p['source_line'];$line['components']=$p['components_after'];$line['mapping_is_manual']=true;$line['sku_identity_version']=1;foreach($p['mappings_before'] as $m){$src=json_decode($m['source_json'],true);$src['sku_identity_version']=1;om_query('UPDATE om_mappings SET source_json=?,components_json=?,saved_by=? WHERE mapping_key=?',[json_encode($src),json_encode($p['components_after']),current_user()['id'],$m['mapping_key']]);}sm_remember_confirmed($p['platform'],$p['shop'],[$line]);$key=om_mapping_key($p['platform'],$p['shop'],$line);om_query('INSERT INTO om_mappings(mapping_key,platform,shop,source_json,components_json,saved_by) VALUES(?,?,?,?,?,?) ON DUPLICATE KEY UPDATE source_json=VALUES(source_json),components_json=VALUES(components_json),saved_by=VALUES(saved_by)',[$key,$p['platform'],$p['shop'],json_encode($line),json_encode($p['components_after']),current_user()['id']]);unset($GLOBALS['SM_MAPPING_ROWS'][$p['platform'].'|'.$p['shop']]);om_query('UPDATE om_orders SET revision=revision+1 WHERE id=?',[$oid]);$saved['approval']=['self_approved'=>(int)$r['requested_by']===(int)current_user()['id'],'approved_by'=>current_user()['id'],'approved_at'=>date('Y-m-d H:i:s'),'new_outflow_id'=>$newId,'undo_outflow_id'=>$undo,'order_record_id'=>$oid];om_query("UPDATE transaction_reversals SET status='Approved',approved_by=?,approved_at=NOW(),result_json=? WHERE id=?",[current_user()['id'],json_encode($saved),$id]);om_event($oid,null,'Posted order item corrected',['source'=>'Admin-approved correction','reason'=>$r['reason'],'reference'=>$ref,'wrong_product'=>$p['from_name'],'correct_product'=>$p['to_name'],'quantity'=>$p['qty'],'stock_changed'=>true,'physical_delta'=>0]);audit('Approve posted order item correction','Outflow',$p['reference'],$ref.'; +'.$p['qty'].' '.$p['from_name'].'; -'.$p['qty'].' '.$p['to_name'].'; exact Seller SKU mapping saved; '.($saved['approval']['self_approved']?'Admin self-approval':'Admin approval'));return $ref;});}
function poc_panel($flows,$title='Correct Posted Order Item'){$allFlows=$flows;$flows=array_values(array_filter($flows,fn($f)=>$f['type']==='Order'&&(int)$f['qty']>0&&$f['reversed_by_request']===null));if(!$allFlows)return;echo '<section class="card"><h3>'.e($title).'</h3><p class="muted small">Approval restores the wrong SKU and deducts the correct SKU on the same platform. Order status and references are preserved.</p>';if($flows&&can_action('resolve_receipt_line')){echo '<details><summary class="btn secondary">Request Item Correction</summary><form method="post" action="actions.php" class="stack" style="margin-top:16px" data-confirm="Submit for Admin approval? Stock and mapping remain unchanged until approval.">';workflow_hidden('poc_request',['return'=>$_GET['page']==='order_monitor'?'order_monitor&order_id='.(int)$_GET['order_id']:'outflow_batch&id='.(int)($_GET['id']??0)]);echo '<label>Wrong posted order item<select name="source_id" required><option value="">Select the source item</option>';foreach($flows as $f){$p=stock_row($f['product_id']);echo '<option value="'.(int)$f['id'].'">'.e($f['order_id'].' · '.$p['master_sku'].' · '.$p['name']).' · '.(int)$f['qty'].' pcs</option>';}echo '</select></label><label>Correct Product / SKU</label>'.picker('to_id','Select the actual dispatched product...',true,'',false).'<details><summary>Historical source evidence — only if no saved Seller SKU / file is available</summary><div class="row"><label>Exact Seller SKU<input name="seller_sku" maxlength="255"></label><label>Platform SKU ID<input name="external_id" maxlength="100"></label><label>Variation<input name="variation" maxlength="255"></label></div></details><label>Reason / original order reference<textarea name="reason" minlength="3" required></textarea></label><label class="ack"><input type="checkbox" name="physical_ack" value="1" required> I verified the actual dispatched product, quantity and Seller SKU against the original order.</label><button class="btn primary">Request Admin Approval</button></form></details>';}
 $seen=[];foreach($allFlows as $f)foreach(poc_requests($f['platform'],$f['order_id']) as $r){if(isset($seen[$r['id']]))continue;$seen[$r['id']]=true;$p=json_decode($r['result_json'],true);echo '<div style="padding:12px 0;border-bottom:1px solid #e1e7ef"><b>REV-'.(int)$r['id'].' · '.e($r['status']).'</b><p>'.e($p['order_no']).' · '.e($p['platform']).'<br>'.e($p['from_name']).' +'.(int)$p['qty'].' pcs → '.e($p['to_name']).' −'.(int)$p['qty'].' pcs</p><p class="muted small">Seller SKU: '.e(sm_value($p['source_line'],$p['platform'])).' · '.e($r['reason']).'<br>Requested: '.e($r['requested_name']).' · '.e($r['created_at']).($r['approved_at']?' · Approved: '.e($r['approved_name']).' · '.e($r['approved_at']):'').(!empty($p['approval']['self_approved'])?' · Admin self-approval':'').'</p><a class="btn ghost sm" href="?page=corrections&amp;request_id='.(int)$r['id'].'">Review Request / Approval</a></div>';}echo '</section>';}
function poc_batch_panel($id){poc_panel(om_query('SELECT * FROM outflows WHERE import_batch_id=? ORDER BY id',[$id])->fetchAll());}
function poc_order_panel($o){poc_panel(om_query('SELECT * FROM outflows WHERE platform=? AND order_id=? ORDER BY id',[$o['platform'],$o['order_no']])->fetchAll());}

